import{_ as r,l as o,o as e,c as n,v as i,p as s,x as t,d,i as _,S as c}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"差分约束","description":"","frontmatter":{"title":"差分约束","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/diff-constraint.md","filePath":"cs/diff-constraint.md","lastUpdated":1789023840000}'),p={name:"cs/diff-constraint.md"};function h(m,a,x,f,E,B){const l=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=i('<h1 id="差分约束" tabindex="-1">差分约束 <a class="header-anchor" href="#差分约束" aria-label="Permalink to &quot;差分约束&quot;">​</a></h1><div class="epigraph"><p>一组 $x_j-x_i\\le c_k$ 有解，当且仅当约束图画出来没有负环；一组解就是某源点的最短路距。</p><footer>—— 据 Bellman, On a Routing Problem, 1958；CLRS 第 24.4 节整理</footer></div><p>上一课<a href="/cs/bellman-ford">Bellman–Ford</a>能在负边图上算单源最短路，并在第 \\(|V|\\) 轮检测可达负环。点名过：不等式可化成边。本课不重写 \\(|V|-1\\) 轮松弛。缺口是把<strong>差分约束系统</strong>写成那张图：变量当顶点，约束当边，可行当且仅当无负环。后课全源换成中间点 DP，不再解不等式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>实数变量 \\(x_1,\\ldots,x_n\\)，约束均形如 \\(x_j-x_i\\le b_{ij}\\)。加一个超源 \\(s\\) 向每个 \\(x_i\\) 连权 \\(0\\) 的边，再对每条约束加边 \\(i\\to j\\)、权 \\(b_{ij}\\)（从 \\(i\\) 走到 \\(j\\) 的边权是 \\(x_j\\) 的上界增量）。若该图无负环，令 \\(x_i=\\delta(s,i)\\)，则三角不等式 \\(\\delta(s,j)\\le\\delta(s,i)+b_{ij}\\) 即 \\(x_j-x_i\\le b_{ij}\\)。有负环则沿环把约束加起来得到 \\(0\\le\\) 负数，不可行。</p><p>缺口不是线性规划单纯形，而是「这组线性不等式 = 一张最短路图」。等式 \\(x_j-x_i=c\\) 拆成两条反向约束。严格不等式在整数变量上改写成 \\(\\le c-1\\)。</p><h3 id="解不是唯一的" tabindex="-1">解不是唯一的 <a class="header-anchor" href="#解不是唯一的" aria-label="Permalink to &quot;解不是唯一的&quot;">​</a></h3><p>最短路给出一组特解。全体解是特解加同一常数（或按连通块平移），因为只约束差。要 \\(x_i\\ge 0\\) 再加边；要最大化某差，仍是最短/最长路，本课只钉可行性与一组可行解。</p><p><span class="marginnote">CLRS 24.4 把差分约束当作 Bellman–Ford 的应用。边权为 \\(b_{ij}\\) 的方向必须与「\\(x_j\\) 不超过 \\(x_i\\) 加这么多」一致；画反则负环含义翻掉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建图 \\(G\\)：\\(n+1\\) 个点。跑 Bellman–Ford。负环 → 报告无解。否则输出 \\(d[i]\\)。代价 \\(O((n+1)(n+m))\\)，与约束条数 \\(m\\) 线性于边。</p>',11)),(e(),s(c,null,{default:t(()=>[_(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INEQ%5B%22x_j%20-%20x_i%20%E2%89%A4%20b%22%5D%20--%3E%20EDGE%5B%22%E8%BE%B9%20i%E2%86%92j%20%E6%9D%83%20b%22%5D%0A%20%20EDGE%20--%3E%20BF%5B%22Bellman%E2%80%93Ford%22%5D%0A%20%20BF%20--%3E%20OK%5B%22d%5Bi%5D%20%E5%8D%B3%E4%B8%80%E7%BB%84%E8%A7%A3%22%5D%0A%20%20BF%20--%3E%20NEG%5B%22%E8%B4%9F%E7%8E%AF%EF%BC%9A%E4%B8%8D%E5%8F%AF%E8%A1%8C%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>约束图不是残量网络，不要把流的反向边请进来。与<a href="/cs/topo-sort">拓扑</a>：若所有 \\(b\\) 使图为 DAG，一轮松弛即可，不必 \\(|V|-1\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最短路三角不等式与差分约束是同一件事的两边。调度里「任务 \\(j\\) 不早于 \\(i\\) 结束加 \\(p\\)」写成这种差；本课不展开车间调度。整数与有理约束在无负环时都有解；无理边权的数值误差与上一课相同。</p><p>不要对约束图跑 Dijkstra：边权 \\(b_{ij}\\) 可负。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不做全源、不写费用流。线性规划一般型（任意 \\(Ax\\le b\\)）不能化成差，那不是本课。后课默认：形如 \\(x_j-x_i\\le c\\) 的系统用最短路；负环即矛盾。稠密全源下一课用 Floyd，对象换成点对距离，不再是变量差。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(x_j-x_i\\le c\\) ↔ 边 \\(i\\to j\\) 权 \\(c\\)；可行 ↔ 无负环。</li><li>超源最短路给出一组解。</li><li>可负权，故用 Bellman–Ford 而非 Dijkstra。</li><li>出处：Bellman, 1958；CLRS 第 24.4 节。</li></ul>',8))])}const j=r(p,[["render",h]]);export{u as __pageData,j as default};
